#!/usr/bin/env bash
# Build tree-sitter-metal: binding skeleton copied from tree-sitter-cuda (renamed), parser
# generated by tree-sitter-cli 0.25 (ABI matching the sandbox's tree-sitter 0.25 runtime),
# external scanner = the C++ grammar's (raw strings), compiled with node-gyp.
set -e
G=/tank/projects/mcp-sandbox-public/grammars
M=$G/tree-sitter-metal
CU=$G/node_modules/tree-sitter-cuda
cd $M
mkdir -p bindings/node src
cp $CU/binding.gyp binding.gyp
cp $CU/bindings/node/binding.cc $CU/bindings/node/index.js $CU/bindings/node/index.d.ts bindings/node/
sed -i 's/tree_sitter_cuda/tree_sitter_metal/g; s/cuda/metal/g; s/CUDA/Metal/g' binding.gyp bindings/node/*
cat > package.json <<'JSON'
{
  "name": "tree-sitter-metal",
  "version": "0.1.0",
  "description": "Metal Shading Language grammar for tree-sitter (extends tree-sitter-cpp)",
  "license": "MIT",
  "main": "bindings/node",
  "types": "bindings/node",
  "dependencies": { "node-addon-api": "^8.5.0", "node-gyp-build": "^4.8.4" },
  "peerDependencies": { "tree-sitter": "^0.25.0" }
}
JSON
cat > tree-sitter.json <<'JSON'
{
  "grammars": [{ "name": "metal", "camelcase": "Metal", "title": "Metal", "scope": "source.metal",
                 "path": ".", "file-types": ["metal"] }],
  "metadata": { "version": "0.1.0", "license": "MIT", "description": "Metal Shading Language grammar" }
}
JSON
# generate the parser (resolves tree-sitter-cpp/grammar from ../node_modules)
NODE_PATH=$G/node_modules npx --yes tree-sitter-cli@0.25.10 generate --abi 15
# the C++ grammar's external scanner, renamed for this language
sed 's/tree_sitter_cpp_external_scanner/tree_sitter_metal_external_scanner/g' $G/node_modules/tree-sitter-cpp/src/scanner.c > src/scanner.c
# compile the node binding (uses node-addon-api / node-gyp-build from ../node_modules)
cd $M && NODE_PATH=$G/node_modules npx --yes node-gyp rebuild
# make it requirable as tree-sitter-metal from the grammars folder
ln -sfn $M $G/node_modules/tree-sitter-metal
echo "built: $(ls build/Release/*.node)"
